def _to_numeric_coord(value: Any) -> float | int:
    """Convert a value to a numeric coordinate for range comparisons.

    Accepts datetimes, timezone-aware datetimes, ISO datetime strings, and
    plain numeric values. Naive datetimes are treated as UTC so that a naive
    datetime, a UTC-aware datetime, and a UTC ISO datetime string all map to
    the same numeric value, regardless of the system timezone. Non-datetime
    values are returned unchanged.
    """
    import datetime

    parsed = _parse_datetime_bound(value)

    if isinstance(parsed, datetime.datetime):
        # Treat naive datetimes as UTC so the numeric value does not depend on
        # the system timezone (datetime.timestamp() uses local time otherwise).
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=datetime.timezone.utc)
        return parsed.timestamp()

    if isinstance(parsed, datetime.date):
        dt = datetime.datetime(
            parsed.year,
            parsed.month,
            parsed.day,
            tzinfo=datetime.timezone.utc,
        )
        return dt.timestamp()

    return parsed


def _bar_value_in_selection_range(
    trace: Any,
    point_idx: int,
    point_value: Any,
    selection_min: Any,
    selection_max: Any,
) -> bool:
    """Return whether a bar's value extent overlaps the selection range.

    A bar spans from its base (default 0) to base + value. Returns False,
    rather than raising, when the value or the trace base is non-numeric
    (e.g. a string).
    """

    def _as_number(value: Any) -> Optional[float]:
        if isinstance(value, bool):
            return None
        if isinstance(value, (int, float)):
            return float(value)
        import numbers

        if isinstance(value, numbers.Number):
            try:
                return float(value)  # type: ignore[arg-type]
            except (TypeError, ValueError):
                return None
        return None

    value_number = _as_number(point_value)
    if value_number is None:
        return False

    base = getattr(trace, "base", None)
    base_value = _get_indexed_value(base, point_idx) if base is not None else 0
    if base_value is None:
        base_value = 0
    base_number = _as_number(base_value)
    if base_number is None:
        return False

    sel_min = _as_number(selection_min)
    sel_max = _as_number(selection_max)
    if sel_min is None or sel_max is None:
        # Allow datetime-like bounds (frontend sends ISO strings) as a fallback.
        try:
            sel_min = float(_to_numeric_coord(selection_min))
            sel_max = float(_to_numeric_coord(selection_max))
        except (TypeError, ValueError):
            return False

    bar_lo = min(base_number, base_number + value_number)
    bar_hi = max(base_number, base_number + value_number)
    lo = min(sel_min, sel_max)
    hi = max(sel_min, sel_max)
    return not (bar_hi < lo or bar_lo > hi)


