    """Return whether an axis is orderable (numeric/datetime) vs categorical.

    Mirrors the numpy-based check without requiring numpy: an axis is orderable
    when both a sample bound and the first data element are orderable values.
    """
    if not _is_orderable_value(bound):
        return False
    for value in data:
        return _is_orderable_value(value)
    return False


def _resolve_axis(
    data: Any, bound_min: Any, bound_max: Any
) -> tuple[list[float], float, float, bool]:
    """Resolve an axis to numeric positions and bounds for range membership.

    For orderable (numeric/datetime) axes, values and bounds are mapped to
    numeric coordinates. For categorical axes, category labels are mapped to
    integer positions so that repeated labels share the same position.

    Returns (positions, lo, hi, is_orderable).
    """
    is_orderable = _axis_is_orderable_generic(data, bound_min)
    if is_orderable:
        positions = [float(_to_numeric_coord(value)) for value in data]
        lo = float(_to_numeric_coord(bound_min))
        hi = float(_to_numeric_coord(bound_max))
    else:
        category_positions: dict[Any, int] = {}
        positions = []
        for value in data:
            if value not in category_positions:
                category_positions[value] = len(category_positions)
            positions.append(float(category_positions[value]))
        lo = float(bound_min)
        hi = float(bound_max)
    return positions, lo, hi, is_orderable


def _position_in_range(
    pos: float, lo: float, hi: float, is_orderable: bool
) -> bool:
    """Return whether a numeric position falls within resolved bounds."""
    if is_orderable:
        return lo <= pos <= hi
    # Categorical: each position spans (pos - 0.5, pos + 0.5).
    return hi > pos - 0.5 and lo < pos + 0.5


def _point_in_polygon(
    x: float, y: float, poly_x: list[float], poly_y: list[float]
) -> bool:
    """Ray-casting point-in-polygon test for a single vertex."""
    n = len(poly_x)
    if n < 3:
        return False

    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly_x[i], poly_y[i]
        xj, yj = poly_x[j], poly_y[j]
        if ((yi > y) != (yj > y)) and (
            x < (xj - xi) * (y - yi) / (yj - yi) + xi
        ):
            inside = not inside
        j = i
    return inside


def _filter_points_with_indices(
    points: Any, indices: Any
) -> tuple[list[dict[str, Any]], list[Any]]:
    """Filter out empty point dicts, keeping indices aligned to valid points."""
    points = points or []
    indices = indices or []

    filtered_points: list[dict[str, Any]] = []
    filtered_indices: list[Any] = []
    for pos, point in enumerate(points):
        if not point:
            continue
        filtered_points.append(point)
        if pos < len(indices):
            filtered_indices.append(indices[pos])
        elif isinstance(point.get("pointIndex"), int):
            filtered_indices.append(point["pointIndex"])
    return filtered_points, filtered_indices


